const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const { chromium } = require('../repos/home-tunnel-server/control-center/node_modules/.pnpm/playwright-core@1.58.2/node_modules/playwright-core');
const out = path.join(__dirname, 'evidence13', 'site');
const origin = process.env.NESTLINK_SITE_ORIGIN || 'http://127.0.0.1:4317';
const source = process.env.NESTLINK_SITE_SOURCE;
function check(value, message) { if (!value) throw new Error(message); }
async function main() {
  check(/^[a-f0-9]{40}$/.test(source || ''), 'Exact committed site source required');
  fs.mkdirSync(out, { recursive: true });
  const browser = await chromium.launch({ headless: true });
  const cases = [], captures = [], faults = [];
  try {
    for (const language of ['zh', 'en']) for (const theme of ['light', 'dark']) {
      const context = await browser.newContext({ colorScheme: theme, reducedMotion: 'reduce' });
      const page = await context.newPage();
      page.on('pageerror', e => faults.push(e.message));
      page.on('response', r => { if (r.url().startsWith(origin) && r.status() >= 400) faults.push(r.url() + ': ' + r.status()); });
      for (const width of [320, 390, 768, 1440]) for (const file of ['index.html', 'preview.html', 'downloads.html', 'privacy.html']) {
        await page.setViewportSize({ width, height: 900 });
        const url = origin + '/' + (language === 'en' ? 'en/' : '') + file + '?theme=' + theme;
        await page.goto(url, { waitUntil: 'networkidle' });
        await page.locator('body').evaluate(() => document.fonts.ready);
        for (const img of await page.locator('img').all()) {
          await img.scrollIntoViewIfNeeded();
          await img.evaluate(image => image.decode());
        }
        await page.evaluate(() => scrollTo(0, 0));
        const geometry = await page.evaluate(() => ({
          viewport: innerWidth, content: document.documentElement.scrollWidth,
          body: document.body.scrollWidth, scrollbar: getComputedStyle(document.documentElement).scrollbarWidth,
          webkitScrollbar: getComputedStyle(document.documentElement, '::-webkit-scrollbar').width,
          stable: document.body.dataset.stableVersion, brand: document.querySelector('.brand').textContent.trim(),
          status: document.querySelector('#download-status')?.textContent,
          tone: document.querySelector('#download-status')?.dataset.tone,
          headingSize: parseFloat(getComputedStyle(document.querySelector('h1')).fontSize),
          images: [...document.images].map(image => ({src: image.getAttribute('src'), loaded: image.complete && image.naturalWidth > 0})),
        }));
        check(geometry.content <= width + 1 && geometry.body <= width + 1, `Horizontal overflow: ${url} @ ${width}: ${JSON.stringify(geometry)}`);
        check(geometry.scrollbar === 'none' || geometry.webkitScrollbar === '0px', 'Visible scrollbar: ' + url);
        check(geometry.stable === '13.0.0' && geometry.brand === 'nestlink', 'Version or brand differs: ' + url);
        check(geometry.headingSize <= 36 && geometry.images.every(image => image.loaded), 'Typography or image load failed: ' + url);
        if (geometry.status) check(geometry.tone === 'ready' && geometry.status.includes('13.0.0'), 'Download status failed: ' + url);
        if (file === 'downloads.html') {
          const buttons = await page.locator('.download-actions a').evaluateAll(links => links.map(link => ({href: link.href, text: link.textContent.trim()})));
          check(buttons.length === 5 && buttons.every(link => link.href.includes('/releases/download/v13.0.0/')), 'Missing platform downloads');
          check(await page.locator('[data-sha256-for]').count() === 11, 'Complete release hash list required');
        }
        if (width <= 800) {
          const menu = page.locator('.nav-toggle');
          await menu.click();
          check(await menu.getAttribute('aria-expanded') === 'true' && await page.locator('#site-nav').isVisible(), 'Menu did not open');
          await page.keyboard.press('Escape');
          check(await menu.getAttribute('aria-expanded') === 'false' && await menu.evaluate(el => el === document.activeElement), 'Menu escape/focus failed');
        }
        await page.locator('[data-theme-choice="dark"]').click();
        check(await page.locator('html').getAttribute('data-theme') === 'dark', 'Dark theme selection failed');
        await page.locator('[data-theme-choice="light"]').click();
        check(await page.locator('html').getAttribute('data-theme') === 'light', 'Light theme selection failed');
        await page.locator('[data-theme-choice="' + theme + '"]').click();
        await page.evaluate(() => scrollTo(0, 0));
        await page.mouse.move(width / 2, 600);
        await page.mouse.wheel(0, 500);
        await page.waitForTimeout(80);
        check(await page.evaluate(() => document.documentElement.scrollHeight <= innerHeight || scrollY > 0), 'Hidden scrollbar prevented scrolling');
        await page.evaluate(() => scrollTo(0, 0));
        if ([390, 1440].includes(width) && ['index.html', 'downloads.html'].includes(file)) {
          const name = `${language}-${file.replace('.html', '')}-${theme}-${width}.png`;
          await page.screenshot({path: path.join(out, name), fullPage: true});
          captures.push({file: name, sha256: crypto.createHash('sha256').update(fs.readFileSync(path.join(out, name))).digest('hex')});
        }
        cases.push({language, theme, width, page: file, geometry, status: 'passed'});
      }
      await context.close();
    }
    for (const language of ['zh', 'en']) {
      const context = await browser.newContext({javaScriptEnabled: false, viewport: {width: 390, height: 900}});
      const page = await context.newPage();
      await page.goto(origin + '/' + (language === 'en' ? 'en/' : '') + 'downloads.html');
      check(await page.locator('.download-actions a').count() === 5, 'Static download links require JavaScript');
      check(await page.locator('[data-sha256-for]').count() === 11, 'Static hashes require JavaScript');
      cases.push({language, javascript: false, status: 'passed', scope: 'Static platform downloads and complete hashes'});
      await context.close();
    }
    const context = await browser.newContext();
    const page = await context.newPage();
    for (const state of ['loading', 'offline', 'error']) {
      await page.goto(origin + '/downloads.html?state=' + state);
      check(await page.locator('#download-status').getAttribute('data-tone') === state, 'Forced download state failed: ' + state);
      check((await page.locator('#download-status').innerText()).includes('13.0.0'), 'Fallback version drift');
      check(await page.locator('.download-actions a').count() === 5, 'Fallback removed downloads');
      cases.push({state, status: 'passed', scope: 'Fallback status retains exact static 13.0.0 downloads'});
    }
    await context.close();
    check(faults.length === 0, 'Page errors: ' + faults.join('; '));
    fs.writeFileSync(path.join(out, 'site-acceptance.json'), JSON.stringify({version: '13.0.0', source_revision: source,
      origin, status: 'passed', cases, captures, faults, scope: 'Actual Chromium layout, navigation, theme, scroll, image, static download and hash checks. Component download bytes verified separately.'}, null, 2) + '\n');
    console.log(JSON.stringify({status: 'passed', cases: cases.length, captures: captures.length, source_revision: source}));
  } finally { await browser.close(); }
}
main().catch(error => { console.error(error.message); process.exitCode = 1; });
